/* Division table: label, commander record name and the group's fuel, ammo
 * and food percentages for divisions with an eligible selected unit. */
void opeu_tbl_draw_groups(uint8_t ds[65536], HostEvent event, uint16_t scratch,
                          uint8_t column, uint8_t first, uint8_t row,
                          uint8_t last, uint8_t flags) {
  uint8_t    a, b;
  uint16_t   c;
  GROUP_PTR  d;
  uint8_t    e;
  uint16_t   f;
  uint8_t    g;
  TEXT_PTR   h;
  uint16_t   i;
  WINDOW_PTR j;
  BUFFER(k, 100, 4);
  j = WINDOW;
  COLUMNS(column, e, row, b, a);
  if (flags & 3) {
    FORMAT(k, GROUP_HEADER);
    POSITION(WIN_COLUMN(j) + e + WIN_X(j) - 0x20, WIN_Y(j) + 1);
    SIDE_COLOR(SIDE);
    PRINT(GROUP_TITLE, k);
  }
  d = GROUP_AT(SIDE, first);
  for (g = first; g <= last; NEXT_GROUP(d), ++g) {
    if (flags & 5) {
      POSITION(WIN_X(j) + 2, (g - TOP) * 17 + WIN_Y(j) + 18);
      SIDE_COLOR(SIDE);
      if (GROUP_FLAGS(d) & 4) {
        if (GROUP_FLAGS(d) & 2)
          PRINT(GROUP_MARK);
        PRINT(GROUP_DIVISION, g + 1);
      } else
        UI_TEXT(GROUP_EMPTY);
    }
    if ((GROUP_FLAGS(d) & 4) && ELIGIBLE(SELECTED(d))) {
      h = RECORD(SIDE, g);
      PERCENT(d, c, i, f);
      FORMAT(k, GROUP_ROW, (GROUP_FLAGS(d) & 8) ? GROUP_DIV : GROUP_ARMY, h, i,
             c, f);
    } else
      COPY(k, GROUP_BLANK);
    POSITION(WIN_COLUMN(j) + e + WIN_X(j) - 0x20,
             (g - TOP) * 17 + WIN_Y(j) + 18);
    TEXT_COLOR(7);
    PUT_RANGE(k, b, a);
  }
  TEXT_COLOR(7);
}

/* Mission table of the current division: each of its four missions shows
 * its order and the objective at the mission cell, or the scaled map cell. */
void opeu_tbl_draw_missions(uint8_t ds[65536], HostEvent event,
                            uint16_t scratch, uint8_t column, uint8_t first,
                            uint8_t row, uint8_t last, uint8_t flags) {
  uint8_t       a, b;
  OBJECTIVE_PTR c;
  uint8_t       d, e;
  MISSION_PTR   f;
  uint8_t       g;
  WINDOW_PTR    h;
  BUFFER(i, 60, 4);
  uint8_t j;
  BUFFER(k, 30, 64);
  h = WINDOW;
  COLUMNS(column, d, row, b, a);
  if (flags & 3) {
    POSITION(0x26, 0x81);
    SIDE_COLOR(SIDE);
    PRINT(MISSION_HEADER);
  }
  f = MISSION_AT(SIDE, GROUP, first);
  for (e = first; e <= last; NEXT_MISSION(f), ++e) {
    if (flags & 5) {
      SIDE_COLOR(SIDE);
      POSITION(WIN_X(h) + 2, (e - TOP) * 17 + WIN_Y(h) + 18);
      PRINT(MISSION_LABEL, e + 1);
    }
    if (MISSION_ORDER(f) != 0xff) {
      c = OBJECTIVE(g = MISSION_X(f), j = MISSION_Y(f));
      if (!c)
        FORMAT(k, MISSION_PLACE, g * SCALE, j * SCALE);
      else
        FORMAT(k, MISSION_TARGET, c);
      FORMAT(i, MISSION_ROW, ORDER_NAME(MISSION_ORDER(f)), k);
    } else
      COPY(i, MISSION_BLANK);
    POSITION(WIN_COLUMN(h) + d + WIN_X(h) - 0x20,
             (e - TOP) * 17 + WIN_Y(h) + 18);
    TEXT_COLOR(7);
    PUT_RANGE(i, b, a);
  }
  TEXT_COLOR(7);
}

